  Asy-Label "LAB420"
  Msg "N" ("420. DECHARGEMENT COUCHES GROUPES CONFIDENTIELS")
  # @ . 
  # TODO: @ADD SYS$*RUNS.REPRISE — unresolved reference
  DataLineOrNoStatement ("LAB420")
  # @ . 
  Delete "C" ("IUNLVG004CO")
  Asy-Cat "P" ("IUNLVG004CO") | Out-Null
  Use ("UNL") "IUNLVG004CO"
  # @ . 
  Xqt "E" ("SYS`$LIB`$*RSA.RSAC-COIVP")
  DataLineOrNoStatement ("BEGIN THREAD FOR UDSSRC READ;")
  DataLineOrNoStatement ("USE DEFAULT QUALIFIER AFLINC;")
  DataLineOrNoStatement ("LOCK TABLE VGD004_GRP_CCH IN EXCLUSIVE RETRIEVAL MODE;")
  DataLineOrNoStatement ("LOCK TABLE VGD003_GRP_CON IN EXCLUSIVE RETRIEVAL MODE;")
  DataLineOrNoStatement ("LOCK TABLE VGD002_GRP_CFL IN EXCLUSIVE RETRIEVAL MODE;")
  DataLineOrNoStatement ("LOCK TABLE VGD006_DET_GRP IN EXCLUSIVE RETRIEVAL MODE;")
  DataLineOrNoStatement ("UNLOAD TO FILE `"UNL`"")
  DataLineOrNoStatement ("SELECT  VGD004_GRP_CCH.* , VGD003_GRP_CON.NO_GRP")
  DataLineOrNoStatement (",VGD006_DET_GRP.NO_GRP_ORI")
  DataLineOrNoStatement (",VGD006_DET_GRP.CD_GRP")
  DataLineOrNoStatement (",VGD006_DET_GRP.DT_DEB_GRP")
  DataLineOrNoStatement (",VGD006_DET_GRP.CD_STA_PFL")
  DataLineOrNoStatement (",VGD006_DET_GRP.CD_STA_GRP")
  DataLineOrNoStatement ("FROM VGD004_GRP_CCH A, VGD003_GRP_CON B, VGD006_DET_GRP C")
  DataLineOrNoStatement ("WHERE VGD003_GRP_CON.NO_RAD_POL =  VGD004_GRP_CCH.NO_RAD_POL")
  DataLineOrNoStatement ("AND VGD003_GRP_CON.NO_SUF_POL =  VGD004_GRP_CCH.NO_SUF_POL")
  DataLineOrNoStatement ("AND VGD003_GRP_CON.CD_TRF     =  VGD004_GRP_CCH.CD_TRF")
  DataLineOrNoStatement ("AND VGD003_GRP_CON.NO_GRP IN")
  DataLineOrNoStatement ("(SELECT DISTINCT (NO_GRP) FROM VGD002_GRP_CFL)")
  DataLineOrNoStatement ("AND  C.NO_GRP = B.NO_GRP")
  DataLineOrNoStatement ("AND  C.NO_SIT     IN (SELECT MAX(NO_SIT)")
  DataLineOrNoStatement ("FROM VGD006_DET_GRP D")
  DataLineOrNoStatement ("WHERE D.NO_GRP = C.NO_GRP  )")
  DataLineOrNoStatement ("ORDER BY  B.NO_GRP,")
  DataLineOrNoStatement ("A.NO_RAD_POL,")
  DataLineOrNoStatement ("A.NO_SUF_POL,")
  DataLineOrNoStatement ("A.CD_TRF,")
  DataLineOrNoStatement ("A.CD_ANN_TRF")
  DataLineOrNoStatement ("FORMAT EXTERNAL;")
  DataLineOrNoStatement ("UNLOCK VGD004_GRP_CCH;")
  DataLineOrNoStatement ("UNLOCK VGD003_GRP_CON;")
  DataLineOrNoStatement ("UNLOCK VGD002_GRP_CFL;")
  DataLineOrNoStatement ("UNLOCK VGD006_DET_GRP;")
  DataLineOrNoStatement ("END THREAD;")
  DataLineOrNoStatement ("EXIT;")
  # @ . 
  Free "" ("IUNLVG004CO")
  # @ . 
  Test "TE/0/S2"
  Jump ("ERRC")
  Jump ("OK")

  Asy-Label "ERRC"
  Msg "" ("** PROBLEME DANS L'UNLOAD VGD004_GRP_CCH **")
  Abort "Runstream aborted"

  Asy-Label "OK"
  Msg "" ("** UNLOAD VGD004_GRP_CCH OK **")
  Time
  # @ . 

